 $allSites=rows('SELECT * FROM ks_sites ORDER BY name');foreach(array_merge(rows('SELECT id,name,email,role,active FROM ks_users WHERE role<>\'system\' ORDER BY active DESC,name'),[null]) as $x){$assigned=$x?array_column(rows('SELECT site_id FROM ks_user_sites WHERE user_id=?',[$x['id']]),'site_id'):[];echo '<details class="card"><summary>'.($x?e($x['name']).' · '.e($x['role']).(!$x['active']?' · Disabled':''):'＋ Add team member').'</summary>';form_start('user');hidden('id',$x['id']??0);echo '<div class="form-grid">';input('name','Full name',$x['name']??'','text','required maxlength="150"');input('email','Email address',$x['email']??'','email','required maxlength="190"');echo '</div><label class="field"><span>Role</span><select name="role">';foreach(['staff'=>'Staff — record and view assigned kitchens','manager'=>'Manager — also manage controls and resolve exceptions','admin'=>'Administrator — all kitchens and users'] as $key=>$label)echo '<option value="'.$key.'" '.(($x['role']??'staff')===$key?'selected':'').'>'.e($label).'</option>';echo '</select></label>';input('password',$x?'New password (leave blank to keep)':'Initial password','','password',($x?'':'required ').'minlength="12" autocomplete="new-password"');echo '<fieldset><legend>Assigned kitchens (administrators can access all)</legend><div class="days">';foreach($allSites as $site)echo '<label><input type="checkbox" name="sites[]" value="'.$site['id'].'" '.(in_array($site['id'],$assigned)?'checked':'').'> '.e($site['name']).'</label>';echo '</div></fieldset><label class="checkline"><input type="checkbox" name="active" '.(!$x||$x['active']?'checked':'').'> Active account</label>';button('Save team member');echo '</form></details>';}
